import os
import sys

def inspect_system_dirs():
    dirs = ['/etc', '/var', '/usr', '/tmp', '/home']
    for d in dirs:
        try:
            entries = os.listdir(d)
            print(f"{d}: {len(entries)} entries")
        except PermissionError:
            print(f"{d}: Permission denied")
        except FileNotFoundError:
            print(f"{d}: Not found")

if __name__ == "__main__":
