```python
import os
import subprocess
import sys

def inspect_system_dirs():
    dirs = ['/etc', '/var', '/usr', '/home', '/tmp', '/opt']
    for d in dirs:
        if os.path.exists(d):
            print(f"=== {d} ===")
            try:
                result = subprocess.run(['ls', '-la', d], capture_output=True, text=True, timeout=5)
                print(result.stdout)
                if result.stderr:
                    print(f"ERRO: {result.stderr}")
            except Exception as e:
                print(f"ERRO ao inspecionar {d}: {e}")
        else:
            print(f"Diretório {d} não existe")

if __name__ == "__main__":
    inspect_system_dirs()
```

