                print(result.stdout)
                if result.stderr:
                    print(f"ERRO: {result.stderr}")
            except Exception as e:
                print(f"ERRO ao inspecionar {d}: {e}")
        else:
            print(f"Diretório {d} não existe")

if __name__ == "__main__":
    inspect_system_dirs()
```

```python
import os
import sys

def inspect_system_dirs():
    dirs = ['/etc', '/var', '/usr', '/home', '/tmp']
    for d in dirs:
        if os.path.exists(d):
            print(f"Directory: {d}")
            try:
                entries = os.listdir(d)
                print(f"  Entries: {len(entries)}")
                for entry in entries[:5]:
                    print(f"    - {entry}")
            except PermissionError:
                print("  Permission denied")
            except Exception as e:
                print(f"  Error: {e}")
        else:
            print(f"Directory not found: {d}")

if __name__ == "__main__":
    inspect_system_dirs()
```

